functions.public.cheongla_save_my_mbti:
CREATE OR REPLACE FUNCTION public.cheongla_save_my_mbti(selected_mbti text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  code text=upper(btrim(selected_mbti));
begin
  if not cheongla_private.can_use_mbti_study() then
    raise exception '승인된 학원 계정으로 이용해 주세요.'
    using errcode='42501';
  end if;

  if code is null or code !~ '^[EI][SN][TF][JP]$' then
    raise exception
      '16가지 MBTI 유형 중 본인의 유형을 선택해 주세요.';
  end if;

  insert into public.cheongla_mbti_preferences(user_id,mbti)
  values((select auth.uid()),code)
  on conflict(user_id)
  do update set
    mbti=excluded.mbti,
    updated_at=clock_timestamp();

  return code;
end;
$function$

functions.public.cheongla_save_mbti_guide:
CREATE OR REPLACE FUNCTION public.cheongla_save_mbti_guide(selected_mbti text, guide_content jsonb, expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous public.cheongla_mbti_guides%rowtype;saved public.cheongla_mbti_guides%rowtype;field text;item jsonb;
begin
 if not(cheongla_private.is_principal()and cheongla_private.can_use_member_services())then
  raise exception '학습법 수정은 승인된 원장만 가능합니다.'using errcode='42501';
 end if;
 if selected_mbti is null or selected_mbti!~'^[IE][NS][TF][JP]$'or guide_content is null or jsonb_typeof(guide_content)<>'object'or octet_length(guide_content::text)>250000 then
  raise exception '유형과 학습법 내용을 확인해 주세요.';
 end if;
 if jsonb_typeof(guide_content->'title')is distinct from 'string'or length(trim(guide_content->>'title'))not between 1 and 200
 or jsonb_typeof(guide_content->'subtitle')is distinct from 'string'or length(guide_content->>'subtitle')>500
 or jsonb_typeof(guide_content->'subjects')is distinct from 'object'
 or jsonb_typeof(guide_content->'groupIntroductions')is distinct from 'object' then raise exception '제목·소개·과목별 자료를 확인해 주세요.';end if;
 foreach field in array array['overview'] loop
  if jsonb_typeof(guide_content->field)is distinct from 'array'then raise exception '유형 이해 내용을 확인해 주세요.';end if;
  if jsonb_array_length(guide_content->field)not between 1 and 30 then raise exception '학습법 항목 수를 확인해 주세요.';end if;
  for item in select value from jsonb_array_elements(guide_content->field)loop
   if jsonb_typeof(item->'title')is distinct from 'string'or length(trim(item->>'title'))not between 1 and 200
   or jsonb_typeof(item->'body')is distinct from 'string'or length(trim(item->>'body'))not between 1 and 30000 then raise exception '항목 제목과 본문을 확인해 주세요.';end if;
  end loop;
 end loop;
 for item in select value from jsonb_each(guide_content->'groupIntroductions')loop
  if jsonb_typeof(item->'title')is distinct from 'string'or length(trim(item->>'title'))not between 1 and 200
  or jsonb_typeof(item->'body')is distinct from 'string'or length(trim(item->>'body'))not between 1 and 30000 then raise exception '과목 소개 제목과 본문을 확인해 주세요.';end if;
 end loop;
 for item in select value from jsonb_each(guide_content->'subjects')loop
  if jsonb_typeof(item)is distinct from 'string'or length(trim(item#>>'{}'))not between 1 and 30000 then raise exception '과목별 본문을 확인해 주세요.';end if;
 end loop;
 guide_content := guide_content - 'coaching';
 perform pg_advisory_xact_lock(hashtext('cheongla_mbti_guides'),hashtext(selected_mbti));
 select *into previous from public.cheongla_mbti_guides where mbti=selected_mbti for update;
 if previous.updated_at is distinct from expected_updated_at then
  raise exception '다른 원장이 내용을 변경했습니다. 작성한 내용을 복사해 보관한 뒤 닫고 다시 확인해 주세요.';
 end if;
 insert into public.cheongla_mbti_guides(mbti,guide,updated_by)values(selected_mbti,guide_content,auth.uid())
 on conflict(mbti)do update set guide=excluded.guide,updated_at=clock_timestamp(),updated_by=excluded.updated_by returning *into saved;
 insert into cheongla_private.mbti_guide_history(mbti,actor_id,before_guide,after_guide)values(selected_mbti,auth.uid(),previous.guide,saved.guide);
 return jsonb_build_object('mbti',saved.mbti,'guide',saved.guide,'updated_at',saved.updated_at);
end;
$function$

functions.cheongla_private.validate_learning:
CREATE OR REPLACE FUNCTION cheongla_private.validate_learning(k text, p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s jsonb;t jsonb;r jsonb;v text;total integer:=0;
begin
 if jsonb_typeof(p) is distinct from 'object' or octet_length(p::text)>50000 then raise exception '양식 내용을 확인해 주세요.';end if;
 if k='study' then
  if jsonb_typeof(p->'subjects')is distinct from 'array' or jsonb_array_length(p->'subjects')<>4 then raise exception '네 과목을 작성해 주세요.';end if;
  if (select count(distinct x->>'key') from jsonb_array_elements(p->'subjects')x where x->>'key'in('korean','math','english','exploration'))<>4 then raise exception '과목이 중복되거나 잘못되었습니다.';end if;
  for s in select * from jsonb_array_elements(p->'subjects') loop
   if coalesce(s->>'minutes','')!~'^[0-9]{1,4}$' or (s->>'minutes')::integer>1440 then raise exception '학습시간은 분 단위로 입력해 주세요.';end if;
   total:=total+(s->>'minutes')::integer;
   if jsonb_typeof(s->'tasks')is distinct from 'array' or jsonb_array_length(s->'tasks')>20 then raise exception '과목별 계획은 20개까지 가능합니다.';end if;
   for t in select * from jsonb_array_elements(s->'tasks')loop
    if jsonb_typeof(t->'text')is distinct from 'string' or length(t->>'text')>1000 or coalesce(t->>'mark','')not in('planned','done','partial','missed')then raise exception '학습계획과 달성 표시를 확인해 주세요.';end if;
   end loop;
  end loop;
  if total>1440 then raise exception '하루 실제 학습시간 합계는 24시간을 넘을 수 없습니다.';end if;
  foreach v in array array['absences','late','away']loop
   if coalesce(p->>v,'')!~'^[0-9]{1,2}$' then raise exception '셀프 점검 횟수를 확인해 주세요.';end if;
  end loop;
  if coalesce(p->>'satisfaction','')not in('high','medium','low','')or length(coalesce(p->>'reflection',''))>3000 or length(coalesce(p->>'seat',''))>30 then raise exception '셀프 점검 내용을 확인해 주세요.';end if;
 elsif k='external' then
  if jsonb_typeof(p->'rows')is distinct from 'array' or jsonb_array_length(p->'rows')not between 1 and 10 then raise exception '외부 수업 일정은 1~10개 입력해 주세요.';end if;
  if coalesce(p->>'until','')!~'^\d{4}-\d{2}-\d{2}$'then raise exception '종료일을 입력해 주세요.';end if;
  for r in select * from jsonb_array_elements(p->'rows')loop
   if jsonb_typeof(r->'days')is distinct from 'array' or jsonb_array_length(r->'days')=0 or exists(select 1 from jsonb_array_elements_text(r->'days')d where d not in('1','2','3','4','5','6','7')) then raise exception '요일을 선택해 주세요.';end if;
   if coalesce(r->>'start','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' or coalesce(r->>'end','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' or (r->>'start')>=(r->>'end')then raise exception '외출·복귀 시간을 확인해 주세요.';end if;
   if length(trim(coalesce(r->>'reason','')))not between 1 and 500 or coalesce(r->>'type','')not in('late','out','early','absent') then raise exception '예외 사유와 유형을 입력해 주세요.';end if;
  end loop;
  if length(coalesce(p->>'note',''))>3000 then raise exception '비고는 3000자까지 가능합니다.';end if;
 elsif k='registration' then
  if length(trim(coalesce(p->>'name','')))not between 1 and 60 then raise exception '학생 이름을 입력해 주세요.';end if;
  if exists(select 1 from jsonb_each(p) where jsonb_typeof(value)<>'string' or length(value#>>'{}')>10000) then raise exception '등록카드 입력 내용을 확인해 주세요.';end if;
 else raise exception '양식 구분을 확인해 주세요.';end if;
end;$function$

functions.cheongla_private.set_mbti_prescription_r:
CREATE OR REPLACE FUNCTION cheongla_private.set_mbti_prescription_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' then
    new.revision := old.revision + 1;
  elsif not exists (select 1 from public.cheongla_profiles where id = new.student_id
    and role = 'student' and approval_status = 'approved' and membership_state = 'active') then
    raise exception '승인된 재원생을 선택해 주세요.';
  end if;
  return new;
end;
$function$

